import { createHash } from 'node:crypto';

const text = (value, name, max = 20000) => {
  if (typeof value !== 'string' || !value.trim() || value.length > max)
    throw Error(name + ' must be a nonempty string ≤ ' + max + ' characters');
  return value;
};

const strings = (value, name, nonempty = true) => {
  if (!Array.isArray(value) || (nonempty && !value.length) || value.length > 50)
    throw Error(name + ' must be an array' + (nonempty ? ' with entries' : ''));
  return value.map((v) => text(v, name, 2000));
};

export function buildPacket(input) {
  text(input.goal, 'goal');
  const constraints = strings(input.constraints, 'constraints'),
    checks = strings(input.checks, 'checks');
  if (!Array.isArray(input.sources) || !input.sources.length) throw Error('sources required');
  const body = [
    '# Current goal\n' + input.goal,
    '# Constraints\n' + constraints.join('\n'),
    '# Selected sources\n' +
      input.sources
        .map(
          (s) =>
            '## ' + text(s.path, 'source path', 500) + '\n' + text(s.text, 'source body', 1000000),
        )
        .join('\n\n'),
    '# Acceptance checks\n' + checks.join('\n'),
  ].join('\n\n');
  return {
    text: body,
    bytes: Buffer.byteLength(body),
    scope: 'Complete supplied text; byte count is not native tokens.',
  };
}

export function validateHandoff(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input))
    throw Error('handoff object required');
  const allowed = ['task_id', 'summary', 'source_anchors', 'findings', 'checks', 'open_questions'];
  if (Object.keys(input).some((k) => !allowed.includes(k))) throw Error('Unknown handoff field');
  if (Buffer.byteLength(JSON.stringify(input), 'utf8') > 12000)
    throw Error('Handoff exceeds 12000 serialized UTF-8 bytes');
  text(input.task_id, 'task_id', 200);
  text(input.summary, 'summary', 2000);
  strings(input.source_anchors, 'source_anchors');
  strings(input.findings, 'findings');
  strings(input.open_questions, 'open_questions', false);
  if (!Array.isArray(input.checks) || !input.checks.length || input.checks.length > 30)
    throw Error('checks required');
  for (const c of input.checks) {
    if (
      !c ||
      typeof c !== 'object' ||
      Array.isArray(c) ||
      Object.keys(c).some((k) => !['command', 'status'].includes(k))
    )
      throw Error('Unknown check field');
    text(c.command, 'check command', 500);
    if (!['passed', 'failed', 'not-run'].includes(c.status))
      throw Error('check status must be passed, failed or not-run');
  }
  return input;
}

export function validateCheckpoint(input) {
  if (!input || typeof input !== 'object') throw Error('checkpoint required');
  text(input.goal, 'goal');
  for (const key of ['constraints', 'source_anchors', 'acceptance_checks'])
    strings(input[key], key);
  strings(input.open_work, 'open_work', false);
  return input;
}

export function boundResult(value, maxChars = 8000) {
  if (typeof value !== 'string') throw Error('text string required');
  if (!Number.isInteger(maxChars) || maxChars < 1 || maxChars > 1000000)
    throw Error('maxChars must be 1–1000000');
  return {
    preview: value.slice(0, maxChars),
    fullText: value,
    sha256: createHash('sha256').update(value).digest('hex'),
    originalBytes: Buffer.byteLength(value),
    truncated: value.length > maxChars,
  };
}

export function auditCache({ provider, usage = {}, before = '', now = '', observedTotal = null }) {
  const num = (v) => (Number.isFinite(v) && v >= 0 ? v : null);

  let total = null,
    read = null,
    write = null,
    fresh = null;
  if (provider === 'openai') {
    total = num(usage.input_tokens);
    read = num(usage.input_tokens_details?.cached_tokens);
    write = num(usage.input_tokens_details?.cache_write_tokens);
    if (total !== null && read !== null && write !== null) fresh = total - read - write;
  } else if (provider === 'anthropic') {
    fresh = num(usage.input_tokens);
    read = num(usage.cache_read_input_tokens);
    write = num(usage.cache_creation_input_tokens);
    if ([fresh, read, write].every((v) => v !== null)) total = fresh + read + write;
  } else if (provider === 'gemini') {
    total = num(observedTotal);
    read = num(usage.total_cached_tokens);
  } else throw Error('provider must be openai, anthropic or gemini');
  if (fresh !== null && fresh < 0) throw Error('Inconsistent usage partitions');
  let common = 0;
  while (common < Math.min(before.length, now.length) && before[common] === now[common]) common++;
  return {
    provider,
    total,
    read,
    write,
    fresh,
    identicalPrefixCharacters: common,
    prefixBeforeSha256: createHash('sha256').update(before).digest('hex'),
    prefixNowSha256: createHash('sha256').update(now).digest('hex'),
    scope:
      'Missing fields stay unknown (null). Character prefix is not a cache-token count or guaranteed hit. Read tokens remain included input.',
  };
}

hook.mjs:
import { pathToFileURL, fileURLToPath } from 'node:url';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { validateHandoff } from './core.mjs';

function saveToolArtifact(response) {
  const directory = path.join(path.dirname(fileURLToPath(import.meta.url)), 'artifacts');
  try {
    fs.mkdirSync(directory);
  } catch (error) {
    if (error.code !== 'EEXIST') throw error;
  }
  if (fs.lstatSync(directory).isSymbolicLink() || !fs.lstatSync(directory).isDirectory())
    throw Error('Artifact directory must be a real directory');
  const body = JSON.stringify(response),
    digest = createHash('sha256').update(body).digest('hex'),
    file = path.join(directory, digest + '.json');
  try {
    fs.writeFileSync(file, body, { flag: 'wx' });
  } catch (error) {
    if (error.code !== 'EEXIST') throw error;
    if (
      fs.lstatSync(file).isSymbolicLink() ||
      !fs.lstatSync(file).isFile() ||
      fs.readFileSync(file, 'utf8') !== body
    )
      throw Error('Artifact path conflict');
  }
  return '.context-kit/artifacts/' + digest + '.json';
}

export function handleHook(event, mode) {
  if (mode === 'results' && event.hook_event_name === 'PostToolUse' && event.tool_name === 'Bash') {
    const r = event.tool_response;
    if (
      !r ||
      typeof r.stdout !== 'string' ||
      typeof r.stderr !== 'string' ||
      r.stderr !== '' ||
      r.interrupted !== false ||
      r.isImage !== false ||
      r.error ||
      (r.exitCode !== undefined && r.exitCode !== 0) ||
      (r.exit_code !== undefined && r.exit_code !== 0) ||
      r.stdout.length <= 8000
    )
      return {};
    // Keep the original structured artifact. Only the model-visible stdout changes.
    const artifact = saveToolArtifact(r),
      suffix =
        '\n[Preview truncated; full structured result: ' +
        artifact +
        '. Read it when omitted facts matter.]';
    return {
      hookSpecificOutput: {
        hookEventName: 'PostToolUse',
        updatedToolOutput: { ...r, stdout: r.stdout.slice(0, 8000 - suffix.length) + suffix },
      },
    };
  }
  if (mode === 'continuity' && event.hook_event_name === 'UserPromptSubmit')
    return {
      hookSpecificOutput: {
        hookEventName: 'UserPromptSubmit',
        additionalContext:
          'Use the latest user request as the current goal. Keep required constraints and ' +
          'acceptance checks explicit. Resolve conflicts by native instruction authority. Verify ' +
          'the artifact against this goal before finishing.',
      },
    };
  if (mode === 'continuity' && event.hook_event_name === 'PreCompact')
    return (
      'Preserve the latest goal, constraints, source anchors, decisions, open work and ' +
      'acceptance checks. Do not claim checks passed without results. Restore referenced ' +
      'source facts when needed after compaction.'
    );
  if (mode === 'handoff' && event.hook_event_name === 'SubagentStart')
    return {
      hookSpecificOutput: {
        hookEventName: 'SubagentStart',
        additionalContext:
          'Stay within the delegated task and source scope. Return a JSON report with task_id, ' +
          'summary, source_anchors, findings, checks (command/status), open_questions. State ' +
          'not-run for checks without results. Validate with the context-kit helper before handoff.',
      },
    };
  if (
    mode === 'handoff' &&
    event.hook_event_name === 'PreToolUse' &&
    event.tool_name === 'SubagentHandback'
  ) {
    try {
      const message = event.tool_input?.message;
      if (typeof message === 'string' && Buffer.byteLength(message, 'utf8') > 12000)
        throw Error('Delivered message exceeds 12000 UTF-8 bytes');
      validateHandoff(typeof message === 'string' ? JSON.parse(message) : message);
      return {};
    } catch (error) {
      return {
        hookSpecificOutput: {
          hookEventName: 'PreToolUse',
          permissionDecision: 'deny',
          permissionDecisionReason: 'Handoff structure invalid: ' + error.message,
        },
      };
    }
  }
  return {};
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  let raw = '';
  for await (const chunk of process.stdin) raw += chunk;
  const output = handleHook(JSON.parse(raw || '{}'), process.argv[2]);
  process.stdout.write(typeof output === 'string' ? output : JSON.stringify(output));
}

run.mjs:
import fs from 'node:fs';
import path from 'node:path';
import {
  buildPacket,
  boundResult,
  validateHandoff,
  validateCheckpoint,
  auditCache,
} from './core.mjs';
const command = process.argv[2],
  file = process.argv[3];
if (!file) {
  console.log(
    'Usage: node run.mjs packet|handoff|checkpoint|cache INPUT.json\n       node run.mjs ' +
      'bound RESULT.txt MAX_CHARS ARTIFACT_DIR\nValidators check structure, not semantic truth ' +
      'or command execution.',
  );
  process.exit(command ? 1 : 0);
}
try {
  let result;
  if (command === 'bound') {
    const out = boundResult(fs.readFileSync(file, 'utf8'), Number(process.argv[4] || 8000)),
      dir = path.resolve(process.argv[5] || '.context-kit/artifacts');
    fs.mkdirSync(dir, { recursive: true });
    const artifact = path.join(dir, out.sha256 + '.txt');
    if (fs.existsSync(artifact) && fs.readFileSync(artifact, 'utf8') !== out.fullText)
      throw Error('Artifact conflict');
    fs.writeFileSync(artifact, out.fullText);
    result = {
      preview: out.preview,
      artifact,
      sha256: out.sha256,
      originalBytes: out.originalBytes,
      truncated: out.truncated,
    };
  } else {
    const input = JSON.parse(fs.readFileSync(file, 'utf8'));
    if (command === 'packet') result = buildPacket(input);
    else if (command === 'handoff') result = validateHandoff(input);
    else if (command === 'checkpoint') result = validateCheckpoint(input);
    else if (command === 'cache') result = auditCache(input);
    else throw Error('Unknown command');
  }
  console.log(JSON.stringify(result, null, 2));
} catch (error) {
  console.error(error.message);
  process.exitCode = 1;
}
